alter table public.primers add column if not exists roadmap_order int;
alter table public.primers add column if not exists content jsonb;
create index if not exists primers_roadmap_order_idx on public.primers (roadmap_order) where author_id is null;

insert into public.primers
  (slug, pattern, title, recognize_when, mental_model, template_md, complexity, mistakes, starter_slugs, roadmap_order, content)
values
('sliding-window',
  'Sliding Window',
  'Sliding Window',
  array['The answer is a contiguous subarray or substring, and the question says longest, shortest, maximum, minimum or how many.', 'There''s a rule the stretch has to satisfy: at most k distinct, no repeats, sum at least target, contains every character of t.', 'A fixed length k is given and you need something about every window of that length.', 'The brute force is two nested loops over start and end. That''s the O(n²) the window removes.']::text[],
  'Keep a window [left, right] and a small summary of what''s inside it: a count map, a running sum, a set. Move right one step at a time to take a new element in. Whenever the window breaks the rule, move left forward until it''s valid again, taking elements out of the summary as they leave.

Neither index ever moves backwards, so each element enters the window once and leaves at most once. That''s why the whole scan is O(n), even though there''s a loop inside a loop.

The shrinking step only works if the rule is monotonic: if a window is invalid, every larger window that contains it is invalid too. "No repeated characters" is like that: adding characters never removes a repeat. When a rule isn''t monotonic (a sum with negative numbers in it), shrinking from the left can skip the answer, and you need a different tool.

Fixed-size windows are the simple case: the window is always k long, so each step adds one element and removes one.',
  'def length_of_longest_substring(s: str) -> int:
    count = {}  # what''s inside the window
    left = best = 0
    for right, ch in enumerate(s):
        # 1. grow: take s[right] in
        count[ch] = count.get(ch, 0) + 1
        # 2. shrink while the window is invalid
        while count[ch] > 1:
            count[s[left]] -= 1
            left += 1
        # 3. valid again: record it
        best = max(best, right - left + 1)
    return best
',
  'Time O(n) · Space O(k), or O(size of the alphabet) for character counts',
  array['Shrinking with if instead of while. One removal isn''t always enough to make the window valid again ("abba" is a quick test).', 'Forgetting to take the left element out of the summary when it leaves: decrement its count, subtract it from the sum.', 'Recording the answer before the window is valid again. Record after the shrink loop.', 'Off-by-one in the length: a window from left to right holds right − left + 1 elements.', 'Leaving zero-count keys in the map when you use the map''s size as "distinct count". Delete them.', 'Reaching for a sum window when the array has negative numbers.']::text[],
  array['maximum-average-subarray-i', 'contains-duplicate-ii', 'maximum-number-of-vowels-in-a-substring-of-given-length']::text[],
  4,
  $json${"version":1,"summary":"For questions about a contiguous stretch of an array or string: the best, longest, shortest or count of subarrays that meet a rule. Two indices walk forward together, so each element is looked at a constant number of times.","prerequisites":["two-pointers"],"walkthrough":{"problemSlug":"longest-substring-without-repeating-characters","input":"s = \"pwwkew\"","steps":[{"window":"[p]","action":"take p","best":"1"},{"window":"[p w]","action":"take w","best":"2"},{"window":"p w [w]","action":"take w → w twice; drop p, drop w","best":"2"},{"window":"p w [w k]","action":"take k","best":"2"},{"window":"p w [w k e]","action":"take e","best":"3"},{"window":"p w w [k e w]","action":"take w → w twice; drop w","best":"3"}],"result":"3, for \"wke\" (or \"kew\")"},"template":{"note":"Grow, shrink while invalid, record. Almost every variable-size window problem is these three lines with a different summary and a different rule.","code":{"python":"def length_of_longest_substring(s: str) -> int:\n    count = {}  # what's inside the window\n    left = best = 0\n    for right, ch in enumerate(s):\n        # 1. grow: take s[right] in\n        count[ch] = count.get(ch, 0) + 1\n        # 2. shrink while the window is invalid\n        while count[ch] > 1:\n            count[s[left]] -= 1\n            left += 1\n        # 3. valid again: record it\n        best = max(best, right - left + 1)\n    return best\n","cpp":"int lengthOfLongestSubstring(const string& s) {\n    unordered_map<char, int> count;  // what's inside the window\n    int left = 0, best = 0;\n    for (int right = 0; right < (int)s.size(); ++right) {\n        char c = s[right];\n        // 1. grow: take s[right] in\n        ++count[c];\n        // 2. shrink while the window is invalid\n        while (count[c] > 1) {\n            --count[s[left]];\n            ++left;\n        }\n        // 3. valid again: record it\n        best = max(best, right - left + 1);\n    }\n    return best;\n}\n","java":"class Solution {\n    public int lengthOfLongestSubstring(String s) {\n        // what's inside the window\n        Map<Character, Integer> count = new HashMap<>();\n        int left = 0, best = 0;\n        for (int right = 0; right < s.length(); right++) {\n            char c = s.charAt(right);\n            // 1. grow: take s[right] in\n            count.merge(c, 1, Integer::sum);\n            // 2. shrink while the window is invalid\n            while (count.get(c) > 1) {\n                count.merge(s.charAt(left), -1, Integer::sum);\n                left++;\n            }\n            // 3. valid again: record it\n            best = Math.max(best, right - left + 1);\n        }\n        return best;\n    }\n}\n"}},"variants":[{"name":"Fixed size k","when":"The window length is given.","idea":"Build the first window once, then slide: add nums[right], remove nums[right − k]. No while loop.","code":{"python":"def find_max_average(nums: list[int], k: int) -> float:\n    # the first window, built once\n    window = sum(nums[:k])\n    best = window\n    for right in range(k, len(nums)):\n        # one in, one out\n        window += nums[right] - nums[right - k]\n        best = max(best, window)\n    return best / k\n","cpp":"double findMaxAverage(const vector<int>& nums, int k) {\n    // the first window, built once\n    long long window = 0;\n    for (int i = 0; i < k; ++i) window += nums[i];\n    long long best = window;\n    for (int right = k; right < (int)nums.size(); ++right) {\n        // one in, one out\n        window += nums[right] - nums[right - k];\n        best = max(best, window);\n    }\n    return (double)best / k;\n}\n","java":"class Solution {\n    public double findMaxAverage(int[] nums, int k) {\n        // the first window, built once\n        long window = 0;\n        for (int i = 0; i < k; i++) window += nums[i];\n        long best = window;\n        for (int right = k; right < nums.length; right++) {\n            // one in, one out\n            window += nums[right] - nums[right - k];\n            best = Math.max(best, window);\n        }\n        return (double) best / k;\n    }\n}\n"},"problemSlug":"maximum-average-subarray-i"},{"name":"Count windows: exactly K = at most K − at most K−1","when":"The question asks how many subarrays have exactly k of something.","idea":"Counting \"exactly\" directly doesn't shrink cleanly, but \"at most\" does: for each right, every window from left to right is valid, so add right − left + 1. Then subtract the at-most-(k−1) count.","code":{"python":"def subarrays_with_k_distinct(nums: list[int], k: int) -> int:\n    def at_most(k: int) -> int:\n        count, left, total = {}, 0, 0\n        for right, x in enumerate(nums):\n            count[x] = count.get(x, 0) + 1\n            # too many distinct: shrink\n            while len(count) > k:\n                count[nums[left]] -= 1\n                if count[nums[left]] == 0:\n                    del count[nums[left]]\n                left += 1\n            # every window that ends at right\n            total += right - left + 1\n        return total\n\n    # exactly k = at most k − at most k−1\n    return at_most(k) - at_most(k - 1)\n","cpp":"long long atMost(const vector<int>& nums, int k) {\n    unordered_map<int, int> count;\n    long long total = 0;\n    int left = 0;\n    for (int right = 0; right < (int)nums.size(); ++right) {\n        ++count[nums[right]];\n        // too many distinct: shrink\n        while ((int)count.size() > k) {\n            if (--count[nums[left]] == 0) {\n                count.erase(nums[left]);\n            }\n            ++left;\n        }\n        // every window that ends at right\n        total += right - left + 1;\n    }\n    return total;\n}\n\nint subarraysWithKDistinct(const vector<int>& nums, int k) {\n    // exactly k = at most k − at most k−1\n    return atMost(nums, k) - atMost(nums, k - 1);\n}\n","java":"class Solution {\n    public int subarraysWithKDistinct(int[] nums, int k) {\n        // exactly k = at most k − at most k−1\n        return atMost(nums, k) - atMost(nums, k - 1);\n    }\n\n    private int atMost(int[] nums, int k) {\n        Map<Integer, Integer> count = new HashMap<>();\n        int left = 0, total = 0;\n        for (int right = 0; right < nums.length; right++) {\n            count.merge(nums[right], 1, Integer::sum);\n            // too many distinct: shrink\n            while (count.size() > k) {\n                int x = nums[left];\n                if (count.merge(x, -1, Integer::sum) == 0) {\n                    count.remove(x);\n                }\n                left++;\n            }\n            // every window that ends at right\n            total += right - left + 1;\n        }\n        return total;\n    }\n}\n"},"problemSlug":"subarrays-with-k-different-integers"},{"name":"Max or min of every window","when":"You need the largest (or smallest) value in each window of size k.","idea":"Keep a deque of indices whose values decrease from front to back. A new value pops every smaller one off the back, since they can't be a maximum again while it's in the window. The front is the answer; drop it once it slides out.","code":{"python":"from collections import deque\n\ndef max_sliding_window(nums: list[int], k: int) -> list[int]:\n    # indices; values decrease from front to back\n    dq = deque()\n    out = []\n    for i, x in enumerate(nums):\n        # smaller values can never be a max again\n        while dq and nums[dq[-1]] <= x:\n            dq.pop()\n        dq.append(i)\n        # the front slid out of the window\n        if dq[0] <= i - k:\n            dq.popleft()\n        # the front is this window's max\n        if i >= k - 1:\n            out.append(nums[dq[0]])\n    return out\n","cpp":"vector<int> maxSlidingWindow(const vector<int>& nums, int k) {\n    // indices; values decrease from front to back\n    deque<int> dq;\n    vector<int> out;\n    for (int i = 0; i < (int)nums.size(); ++i) {\n        // smaller values can never be a max again\n        while (!dq.empty() && nums[dq.back()] <= nums[i]) {\n            dq.pop_back();\n        }\n        dq.push_back(i);\n        // the front slid out of the window\n        if (dq.front() <= i - k) dq.pop_front();\n        // the front is this window's max\n        if (i >= k - 1) out.push_back(nums[dq.front()]);\n    }\n    return out;\n}\n","java":"class Solution {\n    public int[] maxSlidingWindow(int[] nums, int k) {\n        // indices; values decrease from front to back\n        Deque<Integer> dq = new ArrayDeque<>();\n        int[] out = new int[nums.length - k + 1];\n        for (int i = 0; i < nums.length; i++) {\n            int x = nums[i];\n            // smaller values can never be a max again\n            while (!dq.isEmpty() && nums[dq.peekLast()] <= x) {\n                dq.pollLast();\n            }\n            dq.offerLast(i);\n            // the front slid out of the window\n            if (dq.peekFirst() <= i - k) dq.pollFirst();\n            // the front is this window's max\n            if (i >= k - 1) {\n                out[i - k + 1] = nums[dq.peekFirst()];\n            }\n        }\n        return out;\n    }\n}\n"},"problemSlug":"sliding-window-maximum"}],"complexity":{"time":"O(n)","space":"O(k), or O(size of the alphabet) for character counts","why":"left and right each move from 0 to n at most once, so all the shrinking across the whole scan adds up to n steps, not n per step. The deque variant is O(n) for the same reason: each index is pushed once and popped at most once."},"notThis":["Subarray sum equals k with negative numbers allowed: shrinking from the left can skip the answer. Use prefix sums with a hash map.","The elements don't have to be contiguous (subsequences): that's usually DP or greedy.","The pair you're looking for can be anywhere in a sorted array: that's two pointers from both ends, not a window."],"ladder":[{"slug":"maximum-average-subarray-i","tier":"warm-up","note":"Fixed window, a running sum. The smallest possible version."},{"slug":"contains-duplicate-ii","tier":"warm-up","note":"Fixed window kept as a set: is there a repeat within k?"},{"slug":"maximum-number-of-vowels-in-a-substring-of-given-length","tier":"warm-up","note":"Fixed window with a count instead of a sum."},{"slug":"longest-substring-without-repeating-characters","tier":"core","note":"The template itself: grow, shrink while there's a repeat, record."},{"slug":"minimum-size-subarray-sum","tier":"core","note":"Shortest instead of longest: record inside the shrink loop."},{"slug":"max-consecutive-ones-iii","tier":"core","note":"The rule is a budget: at most k zeros in the window."},{"slug":"longest-repeating-character-replacement","tier":"core","note":"Window length minus its most common letter must stay ≤ k."},{"slug":"permutation-in-string","tier":"core","note":"Fixed window compared against a target count."},{"slug":"subarray-product-less-than-k","tier":"core","note":"Counting windows: add right − left + 1 each step."},{"slug":"count-number-of-nice-subarrays","tier":"core","note":"Exactly k odds = at most k − at most k−1."},{"slug":"minimum-window-substring","tier":"stretch","note":"Shortest window that covers every needed character, with a counter of what's still missing."},{"slug":"sliding-window-maximum","tier":"stretch","note":"The monotonic deque."},{"slug":"subarrays-with-k-different-integers","tier":"stretch","note":"Exactly K distinct, the at-most trick at full strength."}]}$json$::jsonb)
